// Input Validation & Normalization
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required fields
if (!requestData.companies || !Array.isArray(requestData.companies)) {
  throw new Error('companies array is required in request body');
}

const validatedCompanies = [];
const errors = [];

for (let i = 0; i < requestData.companies.length; i++) {
  const company = requestData.companies[i];

  if (!company.company_name || company.company_name.trim() === '') {
    errors.push({ index: i, error: 'company_name is required' });
    continue;
  }

  if (!company.job_title || company.job_title.trim() === '') {
    errors.push({ index: i, error: 'job_title is required' });
    continue;
  }

  // Sanitize inputs
  validatedCompanies.push({
    company_name: company.company_name.trim(),
    job_title: company.job_title.trim(),
    first_name: (company.first_name || '').trim(),
    last_name: (company.last_name || '').trim(),
    original_index: i
  });
}

if (validatedCompanies.length === 0) {
  throw new Error('No valid companies found. Errors: ' + JSON.stringify(errors));
}

return [{
  json: {
    companies: validatedCompanies,
    total_input: requestData.companies.length,
    valid_count: validatedCompanies.length,
    validation_errors: errors,
    timestamp: new Date().toISOString()
  }
}];

// Extract companies from current batch
const inputData = $input.first().json;
const companies = inputData.companies || [];

const results = [];

for (const company of companies) {
  results.push({
    json: {
      company_name: company.company_name,
      job_title: company.job_title,
      first_name: company.first_name,
      last_name: company.last_name,
      original_index: company.original_index
    }
  });
}

return results;

// Generate 8 email patterns
const item = $input.first().json;
const firstName = (item.first_name || 'john').toLowerCase();
const lastName = (item.last_name || 'doe').toLowerCase();

// Extract domain from Hunter response or construct from company name
let domain = '';
try {
  if (item.data && item.data.domain) {
    domain = item.data.domain;
  } else {
    // Fallback: construct domain from company name
    domain = item.company_name.toLowerCase()
      .replace(/\s+/g, '')
      .replace(/inc\.?|llc\.?|ltd\.?|corporation|corp\.?/gi, '') + '.com';
  }
} catch (error) {
  domain = item.company_name.toLowerCase().replace(/\s+/g, '') + '.com';
}

const patterns = [
  `${firstName}.${lastName}@${domain}`,
  `${firstName}@${domain}`,
  `${lastName}@${domain}`,
  `${firstName.charAt(0)}.${lastName}@${domain}`,
  `${firstName}${lastName}@${domain}`,
  `${firstName}_${lastName}@${domain}`,
  `${firstName.charAt(0)}${lastName}@${domain}`,
  `${lastName}${firstName.charAt(0)}@${domain}`
];

// Remove duplicates and return
const uniquePatterns = [...new Set(patterns)];

const results = uniquePatterns.map(email => ({
  json: {
    email: email,
    company_name: item.company_name,
    job_title: item.job_title,
    domain: domain,
    first_name: firstName,
    last_name: lastName,
    pattern_type: email.split('@')[0]
  }
}));

return results;

// Consensus Scoring Algorithm
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const email = item.json.email;
    let score = 0;
    let verifiedCount = 0;
    const flags = [];
    const providerResults = {
      hunter: null,
      neverbounce: null,
      debounce: null
    };

    // Parse Hunter.io result
    if (item.json.data && item.json.data.status) {
      providerResults.hunter = item.json.data;
      if (item.json.data.status === 'valid') {
        score += 35;
        verifiedCount++;
      }
      if (item.json.data.accept_all) flags.push('catch-all');
      if (item.json.data.disposable) {
        flags.push('disposable');
        score -= 50;
      }
    }

    // Parse NeverBounce result
    if (item.json.result) {
      providerResults.neverbounce = item.json;
      if (item.json.result === 'valid') {
        score += 35;
        verifiedCount++;
      } else if (item.json.result === 'catchall') {
        flags.push('catch-all');
      } else if (item.json.result === 'disposable') {
        flags.push('disposable');
        score -= 50;
      }
    }

    // Parse Debounce.io result
    if (item.json.debounce) {
      providerResults.debounce = item.json.debounce;
      if (item.json.debounce.send_transactional === '1') {
        score += 30;
        verifiedCount++;
      }
      if (item.json.debounce.disposable === '1') {
        flags.push('disposable');
        score -= 50;
      }
    }

    // Apply catch-all deduction
    if (flags.includes('catch-all')) {
      score -= 15;
    }

    // Ensure score is between 0-100
    score = Math.max(0, Math.min(100, score));

    results.push({
      json: {
        email: email,
        company_name: item.json.company_name,
        job_title: item.json.job_title,
        domain: item.json.domain,
        confidence_score: score,
        verified_by_count: verifiedCount,
        is_deliverable: score >= 85,
        flags: flags,
        provider_results: providerResults,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('Scoring error:', error.message);
    // Continue processing other emails
  }
}

return results;

// Format output and tag quality tier
const item = $input.first().json;

let qualityTag = '';
if (item.confidence_score >= 95) {
  qualityTag = 'Premium';
} else if (item.confidence_score >= 85) {
  qualityTag = 'Good';
} else {
  qualityTag = 'Unverified';
}

return [{
  json: {
    email: item.email,
    company_name: item.company_name,
    job_title: item.job_title,
    domain: item.domain,
    confidence_score: item.confidence_score,
    quality_tag: qualityTag,
    verified_by_count: item.verified_by_count,
    is_deliverable: item.is_deliverable,
    flags: item.flags.join(', '),
    linkedin_profile: item.linkedin_profile_url || '',
    hunter_valid: item.provider_results.hunter?.status === 'valid',
    neverbounce_valid: item.provider_results.neverbounce?.result === 'valid',
    debounce_valid: item.provider_results.debounce?.send_transactional === '1',
    created_at: item.timestamp
  }
}];

// Aggregate all results for response
const allItems = $('Split Email Batch').all();

const verifiedEmails = allItems.filter(item => 
  item.json.is_deliverable && item.json.confidence_score >= 85
);

const totalProcessed = allItems.length;
const totalVerified = verifiedEmails.length;
const avgConfidence = verifiedEmails.reduce((sum, item) => 
  sum + item.json.confidence_score, 0) / (totalVerified || 1);

const premiumCount = verifiedEmails.filter(item => 
  item.json.confidence_score >= 95).length;
const goodCount = verifiedEmails.filter(item => 
  item.json.confidence_score >= 85 && item.json.confidence_score < 95).length;

return [{
  json: {
    success: true,
    summary: {
      total_emails_processed: totalProcessed,
      verified_emails: totalVerified,
      success_rate: ((totalVerified / totalProcessed) * 100).toFixed(2) + '%',
      avg_confidence_score: avgConfidence.toFixed(2),
      premium_contacts: premiumCount,
      good_contacts: goodCount
    },
    verified_contacts: verifiedEmails.map(item => ({
      email: item.json.email,
      company: item.json.company_name,
      job_title: item.json.job_title,
      confidence_score: item.json.confidence_score,
      quality_tag: item.json.quality_tag,
      verified_by_count: item.json.verified_by_count
    })),
    timestamp: new Date().toISOString()
  }
}];
